//! The provider the AI settings make active, as the `llm` port is handed it:
//! what an analysis of notes (`ai.extractFromNotes`) is generated by.
//!
//! `ai.saveSettings` writes the active provider whole on [`SETTINGS`] (the
//! AiSettings aggregate); before any save, the active provider is the one
//! the migration seeds active (`crates/data/migrations/0001_ai_settings.sql`):
//! the cloud API, with no key.

use std::collections::BTreeMap;

use ports_llm::{ApiType, Binary, Models, ProviderConfig, Secret};
use serde_json::Value;

/// The partition whose row [`active`] reads: the one settings row.
pub const SETTINGS: &str = "AiSettings/1";

/// The cloud API's URL, as the migration seeds it.
const CLOUD_URL: &str = "https://api.anthropic.com/v1";

/// The cloud provider's models, as the migration seeds them.
const CLOUD_MODELS: (&str, &str) = ("claude-sonnet-5-5", "claude-haiku-4-5-20251001");

/// The provider `row` — `AiSettings/1` as the engine holds it — makes
/// active; the migration's when it carries none.
pub fn active(row: &BTreeMap<String, Value>) -> ProviderConfig {
    let text = |field: &str| row.get(field).and_then(Value::as_str);
    let models = || Models {
        generation: text("generationModel").unwrap_or_default().to_owned(),
        summary: text("summaryModel").unwrap_or_default().to_owned(),
    };
    match (text("mode"), text("url"), text("binary")) {
        (Some("api"), Some(url), _) => ProviderConfig::Api {
            url: url.to_owned(),
            api_type: match text("detectedApiType") {
                Some("cloud") => Some(ApiType::Cloud),
                Some("opencode") => Some(ApiType::Opencode),
                _ => None,
            },
            key: text("apiKey").map(Secret::new),
            models: models(),
        },
        (Some("binaire"), _, Some("opencode")) => ProviderConfig::Binary {
            binary: Binary::Opencode,
            models: models(),
        },
        (Some("binaire"), _, Some("claude-code")) => ProviderConfig::Binary {
            binary: Binary::ClaudeCode,
            models: models(),
        },
        _ => ProviderConfig::Api {
            url: CLOUD_URL.to_owned(),
            api_type: Some(ApiType::Cloud),
            key: None,
            models: Models {
                generation: CLOUD_MODELS.0.to_owned(),
                summary: CLOUD_MODELS.1.to_owned(),
            },
        },
    }
}

#[cfg(test)]
mod tests {
    use serde_json::json;

    use super::*;

    fn row(fields: Value) -> BTreeMap<String, Value> {
        let Value::Object(fields) = fields else {
            panic!("a row is an object");
        };
        fields.into_iter().collect()
    }

    #[test]
    fn before_any_save_the_cloud_api_the_migration_seeds_is_active() {
        assert_eq!(
            active(&BTreeMap::new()),
            ProviderConfig::Api {
                url: CLOUD_URL.to_owned(),
                api_type: Some(ApiType::Cloud),
                key: None,
                models: Models {
                    generation: "claude-sonnet-5-5".to_owned(),
                    summary: "claude-haiku-4-5-20251001".to_owned(),
                },
            }
        );
    }

    #[test]
    fn a_saved_api_provider_is_active_with_its_type_key_and_models() {
        let saved = row(json!({
            "mode": "api",
            "url": "http://192.168.1.40:4096",
            "detectedApiType": "opencode",
            "apiKey": "sk-maison",
            "binary": null,
            "generationModel": "qwen2.5-32b-instruct",
            "summaryModel": "qwen2.5-14b-instruct"
        }));
        assert_eq!(
            active(&saved),
            ProviderConfig::Api {
                url: "http://192.168.1.40:4096".to_owned(),
                api_type: Some(ApiType::Opencode),
                key: Some(Secret::new("sk-maison")),
                models: Models {
                    generation: "qwen2.5-32b-instruct".to_owned(),
                    summary: "qwen2.5-14b-instruct".to_owned(),
                },
            }
        );
    }

    #[test]
    fn a_saved_api_provider_detected_as_the_cloud_keeps_that_type() {
        let saved = row(json!({
            "mode": "api",
            "url": "https://api.anthropic.com/v1",
            "detectedApiType": "cloud",
            "generationModel": "g",
            "summaryModel": "s"
        }));
        let ProviderConfig::Api { api_type, .. } = active(&saved) else {
            panic!("a saved api is an api provider");
        };
        assert_eq!(api_type, Some(ApiType::Cloud));
    }

    #[test]
    fn a_saved_binary_is_active_with_its_models() {
        for (name, binary) in [
            ("opencode", Binary::Opencode),
            ("claude-code", Binary::ClaudeCode),
        ] {
            let saved = row(json!({
                "mode": "binaire",
                "binary": name,
                "generationModel": "g",
                "summaryModel": "s"
            }));
            assert_eq!(
                active(&saved),
                ProviderConfig::Binary {
                    binary,
                    models: Models {
                        generation: "g".to_owned(),
                        summary: "s".to_owned(),
                    },
                },
                "{name}"
            );
        }
    }
}
